<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Bars\{BarsOfficialAdapter,ProviderFactory};use StudPulse\Domain\{GroupRating,GroupRatingGrades,UserAvatar};use StudPulse\Security\{Auth,RateLimit};final class GroupRatingController{public function board(Auth$a):array{$a->browserOnly();$id=$a->user['id'];$scope=GroupRating::scope($id);if(!$scope)return['group'=>null,'visibility'=>'hidden','items'=>[]];return['group'=>$scope['canonical_code'],'academicYear'=>$scope['academic_year'],'season'=>$scope['season'],'visibility'=>GroupRating::visibility($id),'items'=>GroupRating::board($scope),];}public function me(Auth$a):array{$a->browserOnly();$provider=ProviderFactory::make($a);if(!$provider instanceof BarsOfficialAdapter){throw new ApiError(503,'BLOCKED_EXTERNAL','Подключите БАРС, чтобы загрузить свои оценки.');}$fresh=($_GET['fresh']??'')==='1';if($fresh)RateLimit::check('refresh:group-rating:'.$a->user['id'],1,30);$result=$provider->getGradesAndAssessments('',$fresh);$scope=GroupRating::scope($a->user['id']);$matchingTerm=$scope&&GroupRating::matchesTerm($scope,$result->details['semester']??null);$absences=null;if($matchingTerm&&($_GET['attendance']??'')==='1'&&empty($result->details['stale'])){RateLimit::check('group-rating-attendance:'.$a->user['id'],8,60);try{$attendance=(new BarsOfficialAdapter($a,microtime(true)+9))->getAttendance($scope['term_id']);$absences=GroupRating::attendanceProgress($a->user['id'],$scope,$attendance);}catch(ApiError){}}return[...GroupRatingGrades::summarize($result),'semester'=>$result->details['semester']??null,'groupTermMatches'=>$matchingTerm,'absenceCount'=>$absences,'observedAt'=>$result->observedAt,'stale'=>!empty($result->details['stale']),];}public function card(Auth$a,string$id):array{$a->browserOnly();$scope=GroupRating::scope($a->user['id']);$card=$scope?GroupRating::card($scope,$id):null;if(!$card)throw new ApiError(404,'GROUP_RATING_CARD','Карточка недоступна.');return['group'=>$scope['canonical_code'],'avatarVersion'=>UserAvatar::version($id),...$card];}public function visibility(Auth$a,Request$request):array{$a->browserOnly();$visibility=$request->body['visibility']??null;if(!in_array($visibility,['hidden','average','grades'],true)){throw new ApiError(422,'VALIDATION','Выберите режим видимости рейтинга.');}GroupRating::setVisibility($a->user['id'],$visibility);return['visibility'=>$visibility];}}